import{_ as t,o as d,c as a,a2 as o}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"pgvector Vector Search + Hybrid Ranking + Embedding Cache — Quality Report (v1.26-4)","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/db/vector-search-app.md","filePath":"quality-reports/db/vector-search-app.md"}'),r={name:"quality-reports/db/vector-search-app.md"};function s(c,e,i,n,l,h){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="pgvector-vector-search-hybrid-ranking-embedding-cache-—-quality-report-v1-26-4" tabindex="-1">pgvector Vector Search + Hybrid Ranking + Embedding Cache — Quality Report (v1.26-4) <a class="header-anchor" href="#pgvector-vector-search-hybrid-ranking-embedding-cache-—-quality-report-v1-26-4" aria-label="Permalink to &quot;pgvector Vector Search + Hybrid Ranking + Embedding Cache — Quality Report (v1.26-4)&quot;">​</a></h1><p>Dogfood: <a href="./../../../examples/dogfood-vector-search-app/"><code>examples/dogfood-vector-search-app</code></a>. Package under exercise: <a href="./../../../packages/orm/"><code>@kiwa/orm</code></a> (v0.9) vector-store axis.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>The dogfood exercises the 4 SvelteKit + Kysely + Postgres 16 + pgvector</p><ul><li>Redis patterns the orm package promises in v0.9:</li></ul><ol><li><strong>IVFFlat / HNSW index build with dimension guard</strong> — every write through the store captures the first embedding&#39;s dimensionality and enforces it on every subsequent upsert (<code>src/document/index.ts</code>); the vector index gate (<code>src/index-store/index.ts</code>) wraps <code>@kiwa/orm</code>&#39;s <code>createVectorStoreSession</code> / <code>buildIndex</code> and transitions the session to <code>indexed</code> after mount.</li><li><strong>k-NN semantic search with cosine + L2 distance</strong> — the adapter drives <code>knnSearch</code> through the gate and computes deterministic per-document distances so the ranked list is stable across mock and real. Distance kind (<code>cosine</code> / <code>l2</code>) is captured in the observation so the fidelity harness can assert on the axis.</li><li><strong>Hybrid semantic + BM25 keyword search</strong> — the adapter drives <code>hybridSearch</code> with a <code>vectorWeight</code> in <code>[0, 1]</code> and fuses the cosine / L2 similarity with a BM25-shaped keyword score (<code>bm25Score</code> in <code>src/document/index.ts</code>); ties break on document id ascending so ranking is deterministic.</li><li><strong>Embedding cache with on-demand re-index</strong> — a bounded in-memory embedding cache (<code>src/cache/index.ts</code>) tracks hit + miss counts; <code>driveCacheHitRate</code> runs a 2-pass <code>get → set → get</code> sequence and optionally invalidates every key so the fidelity harness observes cache-hit recovery after re-index.</li></ol><p>All 4 patterns are driven end-to-end through a provider-neutral adapter (<code>src/adapters/interface.ts</code>) with mock (<code>src/adapters/mock.ts</code>) and real (<code>src/adapters/real.ts</code>) implementations.</p><h2 id="release-gate-—-7-axis-verdict-mock-trace" tabindex="-1">Release gate — 7 axis verdict (mock trace) <a class="header-anchor" href="#release-gate-—-7-axis-verdict-mock-trace" aria-label="Permalink to &quot;Release gate — 7 axis verdict (mock trace)&quot;">​</a></h2><p>Snapshot from <a href="./../../../examples/dogfood-vector-search-app/quality-report/fidelity-latest"><code>examples/dogfood-vector-search-app/quality-report/fidelity-latest.md</code></a>.</p><table tabindex="0"><thead><tr><th>axis</th><th>value</th><th>gate</th></tr></thead><tbody><tr><td>coverage — line</td><td>92.00%</td><td>PASS</td></tr><tr><td>coverage — branch</td><td>88.00%</td><td>PASS</td></tr><tr><td>coverage — function</td><td>95.00%</td><td>PASS</td></tr><tr><td>test count — total</td><td>35 (behavior 25 + integration 6 + e2e 4)</td><td>PASS</td></tr><tr><td>fidelity — ratio</td><td>100% mock covered (5/5)</td><td>PASS</td></tr><tr><td>perf — p95</td><td>&lt; 1ms per op</td><td>PASS</td></tr><tr><td>mutation — killRate</td><td>73.33% (22/30)</td><td>PASS</td></tr><tr><td><strong>release gate verdict</strong></td><td><strong>PASS</strong></td><td>7 axes evaluated</td></tr></tbody></table><h2 id="real-vs-mock-fidelity" tabindex="-1">Real vs mock fidelity <a class="header-anchor" href="#real-vs-mock-fidelity" aria-label="Permalink to &quot;Real vs mock fidelity&quot;">​</a></h2><p>The 5-op adapter surface reports 5 behavioral divergences under the default <code>VECTOR_KEY=</code> unset configuration — every real op returns <code>VECTOR_ENV_MISSING</code> while the mock op succeeds. These are well-defined divergences: the fidelity harness records them without failing the release gate because the real adapter is scope-boxed to aliveness in v1.26-4. A future v1.26-6 publish milestone can extend <code>makeConnectedRealAdapter</code> with an actual <code>pg</code> + Kysely + pgvector migration runner once the harness is proved on mock.</p><p>When <code>VECTOR_KEY</code> is set (e.g. <code>postgres://user:pass@localhost:5432/kiwa</code>), the adapter runs a DSN aliveness probe and records <code>probe.ok=true</code>, then falls back to <code>REAL_ADAPTER_NOT_IMPLEMENTED</code> for higher-level ops.</p><h2 id="test-map" tabindex="-1">Test map <a class="header-anchor" href="#test-map" aria-label="Permalink to &quot;Test map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>suite</th><th>file</th><th>count</th></tr></thead><tbody><tr><td>document + index gate contract</td><td><code>tests/semantic-search-e2e.spec.ts</code></td><td>10 (T-DVS-001..010)</td></tr><tr><td>hybrid ranking + BM25 fusion</td><td><code>tests/hybrid-ranking-e2e.spec.ts</code></td><td>6 (T-DVH-001..006)</td></tr><tr><td>cache hit rate + invalidation</td><td><code>tests/cache-hit-rate-e2e.spec.ts</code></td><td>9 (T-DVC-001..009)</td></tr><tr><td>5-op mock E2E</td><td><code>tests/e2e-mock-mode.test.ts</code></td><td>7 (T-DVE-M-001..007)</td></tr><tr><td>fidelity harness</td><td><code>tests/fidelity-report.test.ts</code></td><td>3 (T-DVF-001..003)</td></tr><tr><td>fidelity emit</td><td><code>tests/emit-fidelity-report.test.ts</code></td><td>1 (T-DVE-EM-001)</td></tr><tr><td>real env-gated probe</td><td><code>tests/real-adapter-probe.test.ts</code></td><td>5 (T-DVR-ENV-001..005)</td></tr><tr><td>3-layer perf</td><td><code>tests/perf/dogfood-vector-search-app.perf.ts</code></td><td>1</td></tr></tbody></table><h2 id="extension-roadmap" tabindex="-1">Extension roadmap <a class="header-anchor" href="#extension-roadmap" aria-label="Permalink to &quot;Extension roadmap&quot;">​</a></h2><ul><li>v1.26-6 publish milestone — extend <code>makeConnectedRealAdapter</code> with a real <code>pg</code> + Kysely + pgvector migration runner so the fidelity gap closes and behavioural divergences drop below 5.</li><li>follow-up — add testcontainers Postgres 16 + pgvector + Redis 7 harness under a <code>VECTOR_KEY</code> env-gate so KIWA_MODE=real can spin up a broker in CI without a pre-provisioned instance.</li><li>follow-up — swap the FNV-folded cache key hash for a real hash function (e.g. xxhash64) with a size-bounded lookup table so the cache is production-ready under adversarial keys.</li><li>follow-up — replace the placeholder BM25 with an actual token-frequency <ul><li>document-frequency scorer so hybrid ranking approximates a production tsvector + <code>ts_rank_cd</code> fusion.</li></ul></li></ul>',17)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
